def restore_training_state(self) -> None:
    """Restore the trainer state from the pre-loaded checkpoint.

    This includes the precision settings, loop progress, optimizer states and learning rate scheduler states.

    """
    if not self._loaded_checkpoint:
        return

    # restore precision plugin (scaler etc.)
    self.restore_precision_plugin_state()

    # restore loops and their progress
    self.restore_loops()

    assert self.trainer.state.fn is not None
    if self.trainer.state.fn == TrainerFn.FITTING:
        # restore optimizers and schedulers state
        self.restore_optimizers_and_schedulers()

def restore_precision_plugin_state(self) -> None:
    """Restore the precision plugin state from the pre-loaded checkpoint."""
    if not self._loaded_checkpoint:
        return
    precision_plugin_state = self._loaded_checkpoint.get("precision_plugin")
    if precision_plugin_state:
        self.trainer.precision_plugin.load_state_dict(precision_plugin_state)

def restore_loops(self) -> None:
    """Restore the loop progress from the pre-loaded checkpoint."""
    if not self._loaded_checkpoint:
        return
    fit_loop_state = self._loaded_checkpoint.get("fit_loop")
    if fit_loop_state:
        self.trainer.fit_loop.on_load_checkpoint(fit_loop_state)
