    """Restore the optimizer and scheduler states from the pre-loaded checkpoint."""
    if not self._loaded_checkpoint:
        return
    optimizer_states = self._loaded_checkpoint.get("optimizer_states")
    if optimizer_states:
        for optimizer, state in zip(self.trainer.optimizers, optimizer_states):
            optimizer.load_state_dict(state)
